}

{
  "name": "o3-caller-interaction-id",
  "in": "header",
  "schema": {
    "type": "string"
  },
  "required": false,
  "description": "The interaction ID passed in by the caller, if any"
}

{
  "name": "o3-ozone-interaction-id",
  "in": "header",
  "schema": {
    "type": "string"
  },
  "required": true,
  "description": "An interaction ID generated by Ozone if the caller did not send in one. If the callerInteractionId is specified, this takes the same value."
}

{
  "name": "o3-psu-identifier",
  "in": "header",
  "schema": {
    "type": "string"
  },
  "required": true,
  "description": "A Base64 encoded representation of the psuIdentifier JSON object."
}

{
  "name": "page",
  "in": "query",
  "description": "Page of results to request (standard pagination)",
  "required": true,
  "schema": {
    "default": 1,
    "type": "integer"
  },
  "style": "form"
}

{
  "name": "page-size",
  "in": "query",
  "description": "Page size to request. Default is 100 to comply with the Operating Guidelines for the Open Finance Framework.",
  "required": true,
  "schema": {
    "default": 100,
    "type": "integer"
  },
  "style": "form"
}

{
  "type": "object",
  "required": [
    "AccountId",
    "AccountSubType",
    "Statements"
  ],
  "properties": {
    "AccountId": {
      "description": "\r\nA unique and immutable identifier produced by the LFI to identify the account resource.This identifier has no meaning to the account owner.",
      "type": "string"
    },
    "AccountSubType": {
      "$ref": "#/components/schemas/AEExternalAccountSubTypeCode"
    },
    "Statements": {
      "description": "Array containing details of periodic statements. Each statement includes key financial metrics, balances, summaries, and payment details for a specific statement cycle",
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "StatementId",
          "StatementDate",
          "OpeningDate",
          "ClosingDate",
          "OpeningBalance",
          "ClosingBalance",
          "Summary"
        ],
        "properties": {
          "StatementId": {
            "description": "Unique identifier/reference for the statement",
            "type": "string"
          },
          "StatementDate": {
            "description": "Date the statement was issued/generated",
            "type": "string",
            "format": "date"
          },
          "OpeningDate": {
            "description": "Start date of the statement period",
            "type": "string",
            "format": "date"
          },
          "ClosingDate": {
            "description": "End date of the statement period",
            "type": "string",
            "format": "date"
          },
          "CreditLine": {
            "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyAndAmount_0"
          },
          "OpeningBalance": {
            "allOf": [
              {
                "description": "Object containing opening balance details",
                "type": "object",
                "required": [
                  "CreditDebitIndicator"
                ],
                "properties": {
                  "CreditDebitIndicator": {
                    "$ref": "#/components/schemas/AECreditDebitIndicator"
                  }
                }
              },
              {
                "$ref": "#/components/schemas/AEBalanceWithCategorization"
              }
            ]
          },
          "ClosingBalance": {
            "allOf": [
              {
                "description": "Object containing closing balance details",
                "type": "object",
                "required": [
                  "CreditDebitIndicator"
                ],
                "properties": {
                  "CreditDebitIndicator": {
                    "$ref": "#/components/schemas/AECreditDebitIndicator"
                  }
                }
              },
              {
                "$ref": "#/components/schemas/AEBalanceWithCategorization"
              }
            ]
          },
          "Summary": {
            "description": "Array providing an aggregated summary of financial activities within the statement period, such as Purchase, Repayments, Fee, and Interest/Profit. Each object contains the total aggregated amount, currency, and the count of transactions for the corresponding SubTransactionType.",
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "CreditDebitIndicator",
                "SubTransactionType",
                "Amount",
                "Count"
              ],
              "properties": {
                "CreditDebitIndicator": {
                  "$ref": "#/components/schemas/AECreditDebitIndicator"
                },
                "TransactionType": {
                  "description": "Type of transaction activity.",
                  "type": "string",
                  "enum": [
                    "POS",
                    "ECommerce",
                    "ATM",
                    "BillPayments",
                    "LocalBankTransfer",
                    "SameBankTransfer",
                    "InternationalTransfer",
                    "Teller",
                    "Cheque",
                    "Other"
                  ]
                },
                "SubTransactionType": {
                  "$ref": "#/components/schemas/AESubTransactionType"
                },
                "Amount": {
                  "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyAndAmount_0"
                },
                "Count": {
                  "description": "Number of transactions or occurrences for the transaction type",
                  "type": "number"
                }
              }
            }
          },
          "ExpectedNextStatement": {
            "description": "Object containing projected finance charges or fees expected in the next statement cycle.",
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "minProperties": 1,
              "properties": {
                "Type": {
                  "description": "Statement type.",
                  "type": "string",
                  "enum": [
                    "Purchase",
                    "Reversal",
                    "Refund",
                    "Withdrawal",
                    "WithdrawalReversal",
                    "Deposit",
                    "DepositReversal",
                    "MoneyTransfer",
                    "Repayments",
                    "Interest",
                    "Fee",
                    "Charges",
                    "Profit",
                    "Disbursement",
                    "Adjustment",
                    "Tax",
                    "Rewards",
                    "NotApplicable"
                  ]
                },
                "Amount": {
                  "description": "Statement amount, according to `Type` value.",
                  "type": "object",
                  "required": [
                    "Amount",
                    "Currency"
                  ],
                  "properties": {
                    "Amount": {
                      "$ref": "#/components/schemas/AEActiveCurrencyAndAmount_SimpleType"
                    },
                    "Currency": {
                      "$ref": "#/components/schemas/ActiveOrHistoricCurrencyCode_1"
                    }
                  }
                }
              }
            }
          },
          "NextPayment": {
            "description": "Object containing details related to the next payment due",
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "Date",
                "Amount"
              ],
              "properties": {
                "Date": {
                  "description": "Payment due date",
                  "type": "string",
                  "format": "date"
                },
                "Amount": {
                  "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyAndAmount_0"
                },
                "Type": {
                  "description": "Type of payment - minimum, scheduled, estimated, or other",
                  "type": "string",
                  "enum": [
                    "Minimum",
                    "Scheduled",
                    "Estimated",
                    "Other"
                  ]
                }
              }
            }
          }
        }
      }
    }
  }
}

{
  "type": "object",
  "required": [
    "Amount",
    "Currency"
  ],
  "description": "A given amount value and currency",
  "properties": {
    "Amount": {
      "description": "A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.",
      "type": "string"
    },
    "Currency": {
      "$ref": "#/components/schemas/ActiveOrHistoricCurrencyCode_1"
    }
  },
  "additionalProperties": false
}

{
  "description": "A 3 character alphabetic code allocated to a currency under an international currency identification scheme, as described in the latest edition of the international standard ISO 4217 'Codes for the representation of currencies and funds'.",
  "type": "string",
  "pattern": "^[A-Z]{3,3}$",
  "example": "SAR"
}

{
  "description": "Indicates whether a given balance, transaction, or summarized amount is a credit or a debit.",
  "type": "string",
  "enum": [
    "Credit",
    "Debit"
  ]
}

{
  "type": "object",
  "required": [
    "Amount"
  ],
  "properties": {
    "Amount": {
      "description": "The value of the balance on account, incorporating `Amount` and `Currency`.",
      "type": "object",
      "required": [
        "Amount",
        "Currency"
      ],
      "properties": {
        "Amount": {
          "$ref": "#/components/schemas/AEActiveCurrencyAndAmount_SimpleType"
        },
        "Currency": {
          "$ref": "#/components/schemas/ActiveOrHistoricCurrencyCode_1"
        }
      }
    },
    "Components": {
      "description": "Components of the stated balance, defined by the value of `BalanceCategory`, that reflects a portion of the stated balance.",
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/components/schemas/AEAmountWithCategorization"
      }
    }
  }
}

{
  "description": "A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.",
  "type": "string",
  "pattern": "^\\d{1,13}$|^\\d{1,13}\\.\\d{1,5}$"
}

{
  "type": "object",
  "required": [
    "BalanceCategory",
    "Amount"
  ],
  "properties": {
    "BalanceCategory": {
      "$ref": "#/components/schemas/AEBalanceCategory"
    },
    "BalanceDescription": {
      "description": "Allows a description to provided of the balance to identify the specific Shari’ah compliant charges, payments, and rewards made which can affect the balance.",
      "type": "string",
      "minLength": 1,
      "maxLength": 500
    },
    "Amount": {
      "description": "The value of the categorized balance, incorporating `Amount` and `Currency`.",
      "type": "object",
      "required": [
        "Amount",
        "Currency"
      ],
      "properties": {
        "Amount": {
          "$ref": "#/components/schemas/AEActiveCurrencyAndAmount_SimpleType"
        },
        "Currency": {
          "$ref": "#/components/schemas/ActiveOrHistoricCurrencyCode_1"
        }
      }
    }
  }
}

{
  "type": "object",
  "properties": {
    "totalPages": {
      "type": "number",
      "description": "The number of expected pages for the query.\n"
    },
    "totalRecords": {
      "type": "number",
      "description": "The total number of records in the full set.\n"
    }
  },
  "description": "Metadata relevant to the resource."
}

{
  "description": "Operation failed due to a invalid request parameter",
  "content": {
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/Error400"
      }
    }
  }
}

{
  "description": "Default error response payload structure for Ozone Connect",
  "type": "object",
  "required": [
    "errorCode",
    "errorMessage"
  ],
  "properties": {
    "errorCode": {
      "description": "Error code identifying the problem that occurred. This may either be one of the prescribed Error Code(s) or a namespaced Error Code where the namespace is the system or organisation that has responded with the error, and the code is the code specific to the system or organisation. organisation or system.\nLFIs should implement error codes based on the prescribed codes or guidance in the standards, with non-specific codes maintained for backward compatibility with version 1.2.",
      "anyOf": [
        {
          "type": "string",
          "enum": [
            "Consent.Invalid",
